"""Collects the HTTP + WebSocket route table of the project as plain text.

``collect_routes()`` walks ``django.urls.get_resolver().url_patterns``
recursively and returns sorted lines::

    <full pattern> | <METHODS> | <url name or ->

* DRF function views: the allowed methods come from the class generated by
  ``@api_view``; ViewSets: from ``callback.actions`` (HEAD is ignored - DRF adds
  it lazily at request time, which would make the table order dependent);
* format-suffix variants (``\\.(?P<format>...)``) and DRF API-root views are
  skipped;
* the URL *name* is the bare route name (no namespace) so that renaming apps /
  namespaces does not change the table;
* WebSocket routes are read from the project's ASGI application
  (``settings.ASGI_APPLICATION``) and are emitted as ``WS``.

Nothing is imported from the application packages.
"""
from django.conf import settings
from django.urls import URLResolver, get_resolver
from django.utils.module_loading import import_string
from rest_framework.routers import APIRootView

IGNORED_METHODS = {'options', 'head', 'trace'}


def _segment(pattern):
    """Printable text of one URL pattern without regex anchors."""
    text = str(pattern)
    if text.startswith('^'):
        text = text[1:]
    if text.endswith('$'):
        text = text[:-1]
    return text


def _view_class(callback):
    return getattr(callback, 'cls', None) or getattr(callback, 'view_class', None)


def _methods(callback):
    actions = getattr(callback, 'actions', None)
    if actions:  # ViewSet routed by a router / ``as_view({...})``
        names = [m for m in actions if m.lower() not in IGNORED_METHODS]
        return sorted(m.upper() for m in names)
    cls = _view_class(callback)
    if cls is None:
        return ['?']
    names = getattr(cls, 'http_method_names', [])
    return sorted(m.upper() for m in names
                  if m.lower() not in IGNORED_METHODS and hasattr(cls, m))


def _walk(patterns, prefix=''):
    for entry in patterns:
        text = prefix + _segment(entry.pattern)
        if isinstance(entry, URLResolver):
            yield from _walk(entry.url_patterns, text)
            continue
        if '(?P<format>' in text:  # DRF format suffix variants
            continue
        cls = _view_class(entry.callback)
        if cls is not None and isinstance(cls, type) and issubclass(cls, APIRootView):
            continue
        methods = ','.join(_methods(entry.callback))
        yield f'{text} | {methods} | {entry.name or "-"}'


def _websocket_routes():
    """``(pattern)`` of every websocket route of the ASGI application."""
    application = import_string(settings.ASGI_APPLICATION)
    router = application.application_mapping.get('websocket')
    while router is not None and not hasattr(router, 'routes'):
        # BaseMiddleware keeps the wrapped app in ``inner``, OriginValidator in ``application``
        router = getattr(router, 'inner', None) or getattr(router, 'application', None)
    if router is None:
        return
    for route in router.routes:
        pattern = _segment(route.pattern)
        yield f'{pattern} | WS | {getattr(route, "name", None) or "-"}'


def collect_routes():
    """Sorted route table lines (HTTP and WS)."""
    lines = list(_walk(get_resolver().url_patterns))
    lines.extend(_websocket_routes())
    return sorted(lines)
